import base64,copy,hashlib,re
def route(envelope,repair,fixed_version,budget=2):
    if not isinstance(fixed_version,str) or re.fullmatch(r'[A-Za-z0-9_-]{1,40}',fixed_version) is None:raise ValueError('approved fixed version required')
    if type(budget) is not int or not 1<=budget<=5:raise ValueError('bounded retry policy required')
    if not isinstance(envelope.get('origin_topic'),str) or not envelope['origin_topic']:raise ValueError('source topic required')
    for name in ('partition','offset','attempts'):
        if type(envelope.get(name)) is not int or envelope[name]<(1 if name=='attempts' else 0):raise ValueError('source coordinates/attempts required')
    try:raw=base64.b64decode(envelope['original_b64'],validate=True)
    except Exception as error:raise ValueError('original bytes missing or invalid') from error
    source=copy.deepcopy(envelope);value=raw;destination='parking'
    if envelope['attempts']<budget:
        source['attempts']+=1
        try:
            value=repair(raw)
            if not isinstance(value,bytes) or not 0<len(value)<=65536:raise ValueError('repair must return bounded bytes')
            destination='replay'
        except ValueError:value=raw
    identity=':'.join(str(envelope[name]) for name in ('origin_topic','partition','offset'))+':'+fixed_version
    return {'destination':destination,'key':hashlib.sha256(identity.encode()).hexdigest(),
            'payload':{'source':source,'fix_version':fixed_version,'value_b64':base64.b64encode(value).decode()}}
```

